echo "Submitting ${#RESPONSES[@]} test responses..."
SUCCESS=0
FAIL=0

for i in "${!RESPONSES[@]}"; do
  NUM=$((i + 1))
  RESULT=$(curl -sS -X POST "$BASE/submit" \
    -H "Content-Type: application/json" \
    -d "${RESPONSES[$i]}" 2>&1)
  SUCCESS_FLAG=$(echo "$RESULT" | jq -r '.success // empty' 2>/dev/null)
  if [ "$SUCCESS_FLAG" = "true" ]; then
    RESPONSE_ID=$(echo "$RESULT" | jq -r '.response_id')
    echo "  [$NUM] OK - response_id: $RESPONSE_ID"
    SUCCESS=$((SUCCESS + 1))
  else
    echo "  [$NUM] FAIL - $RESULT"
    FAIL=$((FAIL + 1))
  fi
  sleep 0.3
done

echo ""
echo "Done: $SUCCESS succeeded, $FAIL failed"
